cat > /workspace/trdsql.py << 'PYEOF'
#!/usr/bin/env python3
"""trdsql - Execute SQL queries on CSV, LTSV, JSON, YAML and TBLN files."""

import sys
import os
import re
import csv
import json
import io
import sqlite3
import argparse
import gzip
import bz2
import lzma
import datetime
import subprocess
from collections import OrderedDict

VERSION = "devel"

def log_error(msg):
    now = datetime.datetime.now()
    ts = now.strftime("%Y/%m/%d %H:%M:%S")
    print(f"{ts} {msg}", file=sys.stderr)

def is_numeric(s):
    """Check if a string looks like a simple number (for alignment purposes)."""
    if s is None:
        return False
    return bool(re.match(r'^-?[0-9]+(\.[0-9]+)?$', s))

# ============================================================
# Input readers
# ============================================================

def read_csv(f, delimiter=',', has_header=False, skip=0, limit=0, preread=1, null_values=None, add_num=False):
    """Read CSV format. Returns (columns, rows)."""
    reader = csv.reader(f, delimiter=delimiter if delimiter != '\\t' else '\t')
    rows_raw = []
    for row in reader:
        if row:  # skip empty rows
            rows_raw.append(row)

    # Skip header rows
    if skip > 0:
        rows_raw = rows_raw[skip:]

    if not rows_raw:
        return [], []

    # Determine columns
    if has_header and rows_raw:
        columns = rows_raw[0]
        data_rows = rows_raw[1:]
    else:
        # Use preread rows to determine column count
        max_cols = max(len(r) for r in rows_raw[:max(preread, 1)]) if rows_raw else 0
        columns = [f'c{i+1}' for i in range(max_cols)]
        data_rows = rows_raw

    # Apply limit
    if limit > 0:
        data_rows = data_rows[:limit]

    # Process null values
    if null_values:
        data_rows = [[None if cell in null_values else cell for cell in row] for row in data_rows]

    # Add row number column
    if add_num:
        columns = ['num'] + columns
        data_rows = [[str(i+1)] + row for i, row in enumerate(data_rows)]

    # Pad/trim rows to match column count
    ncols = len(columns)
    data_rows = [row[:ncols] + [''] * max(0, ncols - len(row)) for row in data_rows]

    return columns, data_rows

def read_ltsv(f, limit=0, null_values=None, add_num=False):
    """Read LTSV format. Returns (columns, rows)."""
    columns = None
    rows = []
    for line in f:
        if isinstance(line, bytes):
            line = line.decode('utf-8')
        line = line.rstrip('\n\r')
        if not line:
            continue
        fields = line.split('\t')
        record = OrderedDict()
        for field in fields:
            if ':' in field:
                k, v = field.split(':', 1)
                record[k] = v
            else:
                record[field] = ''
        if columns is None:
            columns = list(record.keys())
        rows.append([record.get(c, '') for c in columns])
        if limit > 0 and len(rows) >= limit:
            break

    if columns is None:
        columns = []

    if null_values:
        rows = [[None if cell in null_values else cell for cell in row] for row in rows]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i+1)] + row for i, row in enumerate(rows)]

    return columns, rows

def _json_to_rows(data, jq_expr=None):
    """Convert JSON data to (columns, rows)."""
    if jq_expr:
        # Use jq binary to process
        import subprocess
        proc = subprocess.run(['jq', '-c', jq_expr], 
                              input=json.dumps(data).encode(),
                              capture_output=True)
        if proc.returncode != 0:
            raise ValueError(f"gojq:{jq_expr} {proc.stderr.decode().strip()}")
        lines = proc.stdout.decode().strip().split('\n')
        results = []
        for line in lines:
            if line:
                results.append(json.loads(line))
        data = results

    if not isinstance(data, list):
        data = [data]

    if not data:
        return [], []

    # Determine if it's a list of scalars or objects
    columns = None
    rows = []

    for item in data:
        if isinstance(item, dict):
            if columns is None:
                columns = list(item.keys())
            row = []
            for c in columns:
                v = item.get(c, '')
                if isinstance(v, (dict, list)):
                    row.append(json.dumps(v, separators=(',', ':')))
                elif v is None:
                    row.append(None)
                elif isinstance(v, bool):
                    row.append('true' if v else 'false')
                else:
                    row.append(str(v))
            rows.append(row)
        else:
            # Scalar
            if columns is None:
                columns = ['c1']
            if item is None:
                rows.append([None])
            elif isinstance(item, bool):
                rows.append(['true' if item else 'false'])
            else:
                rows.append([str(item)])

    if columns is None:
        columns = []

    return columns, rows

def read_json(f, jq_expr=None, limit=0, null_values=None, add_num=False, preread=1):
    """Read JSON format. Returns (columns, rows)."""
    content = f.read()
    if isinstance(content, bytes):
        content = content.decode('utf-8')

    # Try to parse as JSONL (one object per line) or single JSON
    lines = [l for l in content.strip().split('\n') if l.strip()]

    data = None
    is_jsonl = False

    # Try single JSON first
    try:
        data = json.loads(content)
    except json.JSONDecodeError:
        # Try JSONL
        try:
            data = [json.loads(line) for line in lines if line.strip()]
            is_jsonl = True
        except json.JSONDecodeError as e:
            raise ValueError(f"JSON parse error: {e}")

    columns, rows = _json_to_rows(data, jq_expr)

    if limit > 0:
        rows = rows[:limit]

    if null_values:
        rows = [[None if cell in null_values else cell for cell in row] for row in rows]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i+1)] + row for i, row in enumerate(rows)]

    return columns, rows

def read_yaml(f, limit=0, null_values=None, add_num=False):
    """Read YAML format. Returns (columns, rows)."""
    content = f.read()
    if isinstance(content, bytes):
        content = content.decode('utf-8')

    # Simple YAML parser for the format used by trdsql
    data = parse_simple_yaml(content)

    columns, rows = _json_to_rows(data)

    if limit > 0:
        rows = rows[:limit]

    if null_values:
        rows = [[None if cell in null_values else cell for cell in row] for row in rows]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i+1)] + row for i, row in enumerate(rows)]

    return columns, rows

def parse_simple_yaml(content):
    """Parse simple YAML: list of objects or scalars."""
    lines = content.split('\n')
    result = []
    current_obj = None
    in_list = False

    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.rstrip()

        if not stripped or stripped.startswith('#'):
            i += 1
            continue

        indent = len(line) - len(line.lstrip())

        if stripped.startswith('- '):
            # New list item
            rest = stripped[2:].strip()
            if rest == '':
                # Empty item start - next lines are properties
                current_obj = OrderedDict()
                result.append(current_obj)
                i += 1
                continue

            if ':' in rest and not rest.startswith('"') and not rest.startswith("'"):
                # First key-value of a new object
                current_obj = OrderedDict()
                result.append(current_obj)
                k, v = rest.split(':', 1)
                k = k.strip()
                v = v.strip()
                current_obj[k] = parse_yaml_value(v)
            else:
                # Scalar list item
                result.append(parse_yaml_value(rest))
                current_obj = None
        elif stripped.startswith('-') and stripped == '-':
            current_obj = OrderedDict()
            result.append(current_obj)
        elif ':' in stripped and current_obj is not None and indent > 0:
            # Key-value within current object
            k, v = stripped.split(':', 1)
            k = k.strip()
            v = v.strip()
            current_obj[k] = parse_yaml_value(v)

        i += 1

    return result

def parse_yaml_value(v):
    """Parse a YAML scalar value."""
    if not v:
        return ''
    if v.startswith('"') and v.endswith('"'):
        return v[1:-1].replace('\\"', '"')
    if v.startswith("'") and v.endswith("'"):
        return v[1:-1]
    if v == 'true':
        return True
    if v == 'false':
        return False
    if v == 'null' or v == '~':
        return None
    return v

def read_tbln(f, limit=0, null_values=None, add_num=False):
    """Read TBLN format. Returns (columns, rows)."""
    columns = None
    rows = []

    for line in f:
        if isinstance(line, bytes):
            line = line.decode('utf-8')
        line = line.rstrip('\n\r')

        if line.startswith(';'):
            # Metadata line
            # ; name: | col1 | col2 | ... |
            m = re.match(r';\s*name:\s*\|(.*)\|', line)
            if m:
                parts = m.group(1).split('|')
                columns = [p.strip() for p in parts]
        elif line.startswith('|'):
            # Data row
            parts = line.split('|')
            # Remove first and last empty parts
            parts = parts[1:-1]
            row = [p.strip() for p in parts]
            rows.append(row)
            if limit > 0 and len(rows) >= limit:
                break

    if columns is None:
        if rows:
            columns = [f'c{i+1}' for i in range(len(rows[0]))]
        else:
            columns = []

    if null_values:
        rows = [[None if cell in null_values else cell for cell in row] for row in rows]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i+1)] + row for i, row in enumerate(rows)]

    return columns, rows

def read_text(f, limit=0, null_values=None, add_num=False):
    """Read text format (one line = one row). Returns (columns, rows)."""
    columns = ['text']
    rows = []
    for line in f:
        if isinstance(line, bytes):
            line = line.decode('utf-8')
        line = line.rstrip('\n\r')
        rows.append([line])
        if limit > 0 and len(rows) >= limit:
            break

    if null_values:
        rows = [[None if cell in null_values else cell for cell in row] for row in rows]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i+1)] + row for i, row in enumerate(rows)]

    return columns, rows

def read_width(f, limit=0, null_values=None, add_num=False):
    """Read width/fixed-width format. Returns (columns, rows)."""
    lines = []
    for line in f:
        if isinstance(line, bytes):
            line = line.decode('utf-8')
        line = line.rstrip('\n\r')
        lines.append(line)

    if not lines:
        return [], []

    # First line defines column boundaries
    header_line = lines[0]
    # Find column boundaries based on whitespace in header
    col_starts = []
    col_names = []

    # Split header into words and track their positions
    i = 0
    while i < len(header_line):
        if header_line[i] != ' ':
            j = i
            while j < len(header_line) and header_line[j] != ' ':
                j += 1
            col_starts.append(i)
            col_names.append(header_line[i:j].strip())
            i = j
        else:
            i += 1

    columns = col_names
    rows = []

    for line in lines[1:]:
        row = []
        for idx, start in enumerate(col_starts):
            if idx + 1 < len(col_starts):
                end = col_starts[idx + 1]
                val = line[start:end].strip() if start < len(line) else ''
            else:
                val = line[start:].strip() if start < len(line) else ''
            row.append(val)
        rows.append(row)
        if limit > 0 and len(rows) >= limit:
            break

    if null_values:
        rows = [[None if cell in null_values else cell for cell in row] for row in rows]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i+1)] + row for i, row in enumerate(rows)]

    return columns, rows

# ============================================================
# File format detection
# ============================================================

def guess_format(filename):
    """Guess file format from extension."""
    if filename == '-':
        return 'csv'

    # Extract the base filename (handle :: syntax)
    base = filename.split('::')[0]

    ext = os.path.splitext(base)[1].lower()
    # Handle compressed files
    if ext in ('.gz', '.bz2', '.zst', '.lz4', '.xz'):
        base2 = os.path.splitext(base[:-len(ext)])[0]
        ext = os.path.splitext(base2)[1].lower()

    format_map = {
        '.csv': 'csv',
        '.tsv': 'csv',
        '.ltsv': 'ltsv',
        '.json': 'json',
        '.jsonl': 'json',
        '.ndjson': 'json',
        '.yaml': 'yaml',
        '.yml': 'yaml',
        '.tbln': 'tbln',
    }
    return format_map.get(ext, 'csv')

# ============================================================
# Output formatters
# ============================================================

def format_csv(rows, columns, delimiter=',', quote_char='"', quote_all=False, 
               header=False, crlf=False, null_value=''):
    """Format as CSV."""
    output = io.StringIO()

    quoting = csv.QUOTE_ALL if quote_all else csv.QUOTE_MINIMAL
    writer = csv.writer(output, delimiter=delimiter, quotechar=quote_char, 
                        quoting=quoting, lineterminator='\r\n' if crlf else '\n')

    if header:
        writer.writerow(columns)

    for row in rows:
        processed = [null_value if v is None else v for v in row]
        writer.writerow(processed)

    return output.getvalue()

def format_raw(rows, columns, delimiter=',', header=False, crlf=False, null_value=''):
    """Format as raw (no quoting)."""
    lines = []

    if header:
        lines.append(delimiter.join(columns))

    for row in rows:
        processed = [null_value if v is None else str(v) for v in row]
        lines.append(delimiter.join(processed))

    sep = '\r\n' if crlf else '\n'
    result = sep.join(lines)
    if lines:
        result += sep
    return result

def format_json(rows, columns, null_value=''):
    """Format as JSON array."""
    result = []
    for row in rows:
        obj = OrderedDict()
        for i, col in enumerate(columns):
            v = row[i] if i < len(row) else ''
            if v is None:
                obj[col] = null_value if null_value else None
            else:
                obj[col] = v
        result.append(obj)

    return json.dumps(result, indent=2, ensure_ascii=False) + '\n'

def format_jsonl(rows, columns, null_value=''):
    """Format as JSON Lines."""
    lines = []
    for row in rows:
        obj = OrderedDict()
        for i, col in enumerate(columns):
            v = row[i] if i < len(row) else ''
            if v is None:
                obj[col] = null_value if null_value else None
            else:
                obj[col] = v
        lines.append(json.dumps(obj, ensure_ascii=False))
    return '\n'.join(lines) + '\n' if lines else ''

def format_ltsv(rows, columns, null_value='', crlf=False):
    """Format as LTSV."""
    lines = []
    for row in rows:
        parts = []
        for i, col in enumerate(columns):
            v = row[i] if i < len(row) else ''
            if v is None:
                v = null_value
            parts.append(f"{col}:{v}")
        lines.append('\t'.join(parts))

    sep = '\r\n' if crlf else '\n'
    return sep.join(lines) + sep if lines else ''

def format_yaml(rows, columns, null_value=''):
    """Format as YAML."""
    lines = []
    for row in rows:
        first = True
        for i, col in enumerate(columns):
            v = row[i] if i < len(row) else ''
            if v is None:
                v = null_value if null_value else None

            if first:
                prefix = '- '
                first = False
            else:
                prefix = '  '

            if v is None:
                lines.append(f"{prefix}{col}: null")
            else:
                # Check if value needs quoting
                lines.append(f"{prefix}{col}: {v}")
    return '\n'.join(lines) + '\n' if lines else ''

def format_tbln(rows, columns, null_value='', crlf=False):
    """Format as TBLN."""
    lines = []
    # Header
    names = ' | '.join(columns)
    lines.append(f"; name: | {names} |")
    types = ' | '.join(['text'] * len(columns))
    lines.append(f"; type: | {types} |")

    # Data
    for row in rows:
        parts = []
        for i, col in enumerate(columns):
            v = row[i] if i < len(row) else ''
            if v is None:
                v = null_value
            parts.append(f" {v} ")
        lines.append('|' + '|'.join(parts) + '|')

    sep = '\r\n' if crlf else '\n'
    return sep.join(lines) + sep if lines else ''

def format_vf(rows, columns, null_value='', crlf=False):
    """Format as vertical format."""
    lines = []
    max_col_len = max(len(c) for c in columns) if columns else 0

    for i, row in enumerate(rows):
        lines.append(f"---[{i+1:2d}]------------------------")
        for j, col in enumerate(columns):
            v = row[j] if j < len(row) else ''
            if v is None:
                v = null_value
            lines.append(f"{col:>{max_col_len}} | {v}")

    sep = '\r\n' if crlf else '\n'
    return sep.join(lines) + sep if lines else ''

def _calc_col_widths(rows, columns):
    """Calculate column widths for AT/MD format."""
    widths = [len(c) for c in columns]
    for row in rows:
        for i, v in enumerate(row):
            if i < len(widths):
                vstr = '' if v is None else str(v)
                widths[i] = max(widths[i], len(vstr))
    return widths

def format_at(rows, columns, null_value='', nowrap=False, crlf=False):
    """Format as ASCII Table."""
    widths = _calc_col_widths(rows, columns)

    sep = '\r\n' if crlf else '\n'
    lines = []

    # Top border
    border = '+' + '+'.join('-' * (w + 2) for w in widths) + '+'
    lines.append(border)

    # Header row (centered)
    header_parts = []
    for i, col in enumerate(columns):
        w = widths[i]
        header_parts.append(' ' + col.center(w) + ' ')
    lines.append('|' + '|'.join(header_parts) + '|')

    # Separator
    lines.append(border)

    # Data rows
    for row in rows:
        parts = []
        for i, v in enumerate(row):
            if i >= len(widths):
                break
            w = widths[i]
            vstr = '' if v is None else str(v)
            if v is None:
                vstr = null_value
            if is_numeric(vstr):
                parts.append(' ' + vstr.rjust(w) + ' ')
            else:
                parts.append(' ' + vstr.ljust(w) + ' ')
        lines.append('|' + '|'.join(parts) + '|')

    # Bottom border
    lines.append(border)

    return sep.join(lines) + sep

def format_md(rows, columns, null_value='', nowrap=False, crlf=False):
    """Format as Markdown table."""
    widths = _calc_col_widths(rows, columns)

    sep = '\r\n' if crlf else '\n'
    lines = []

    # Header row (centered)
    header_parts = []
    for i, col in enumerate(columns):
        w = widths[i]
        header_parts.append(' ' + col.center(w) + ' ')
    lines.append('|' + '|'.join(header_parts) + '|')

    # Separator row
    sep_parts = []
    for w in widths:
        sep_parts.append('-' * (w + 2))
    lines.append('|' + '|'.join(sep_parts) + '|')

    # Data rows
    for row in rows:
        parts = []
        for i, v in enumerate(row):
            if i >= len(widths):
                break
            w = widths[i]
            vstr = '' if v is None else str(v)
            if v is None:
                vstr = null_value
            if is_numeric(vstr):
                parts.append(' ' + vstr.rjust(w) + ' ')
            else:
                parts.append(' ' + vstr.ljust(w) + ' ')
        lines.append('|' + '|'.join(parts) + '|')

    return sep.join(lines) + sep if lines else ''

# ============================================================
# SQL parsing - find table names
# ============================================================

def tokenize_sql(sql):
    """Tokenize SQL into tokens. Returns list of (token, is_whitespace) tuples."""
    tokens = []
    i = 0
    while i < len(sql):
        c = sql[i]

        if c in (' ', '\t', '\n', '\r'):
            # Whitespace
            j = i
            while j < len(sql) and sql[j] in (' ', '\t', '\n', '\r'):
                j += 1
            tokens.append((' ', True))
            i = j
        elif c == '\'':
            # Single-quoted string
            j = i + 1
            while j < len(sql):
                if sql[j] == '\'' and (j + 1 >= len(sql) or sql[j+1] != '\''):
                    j += 1
                    break
                elif sql[j] == '\'' and sql[j+1] == '\'':
                    j += 2
                else:
                    j += 1
            tokens.append((sql[i:j], False))
            i = j
        elif c == '"':
            # Double-quoted string
            j = i + 1
            while j < len(sql):
                if sql[j] == '"' and (j + 1 >= len(sql) or sql[j+1] != '"'):
                    j += 1
                    break
                elif sql[j] == '"' and sql[j+1] == '"':
                    j += 2
                else:
                    j += 1
            tokens.append((sql[i:j], False))
            i = j
        elif c == '`':
            # Backtick-quoted identifier
            j = i + 1
            while j < len(sql) and sql[j] != '`':
                j += 1
            if j < len(sql):
                j += 1
            tokens.append((sql[i:j], False))
            i = j
        elif c in ('(', ')', ',', '=', '<', '>', '!', '+', '-', '*', '/', ';', '.'):
            tokens.append((c, False))
            i += 1
        else:
            # Word/identifier
            j = i
            while j < len(sql) and sql[j] not in (' ', '\t', '\n', '\r', '(', ')', ',', '=', '<', '>', '!', '+', '-', '*', '/', ';', '\'', '"', '`'):
                j += 1
            tokens.append((sql[i:j], False))
            i = j

    return tokens

def find_table_names(sql):
    """Find table names in SQL. Returns list of table names."""
    tokens = tokenize_sql(sql)

    # Keywords that precede table names
    table_keywords = {'from', 'join', 'into', 'update', 'table'}

    table_names = []
    i = 0
    non_ws_tokens = [(t, is_ws) for t, is_ws in tokens]

    # Get non-whitespace tokens with positions
    nws = [(t, idx) for idx, (t, is_ws) in enumerate(non_ws_tokens) if not is_ws]

    for j, (tok, orig_idx) in enumerate(nws):
        if tok.lower() in table_keywords:
            # Next non-whitespace token is the table name
            k = j + 1
            if k < len(nws):
                next_tok, next_idx = nws[k]
                if next_tok == '(':
                    continue  # Subquery, skip
                if next_tok.upper() in ('SELECT', 'WITH'):
                    continue  # Subquery
                # It's a table name
                if next_tok.startswith('`'):
                    # Already backtick-quoted
                    name = next_tok[1:-1]
                else:
                    name = next_tok
                if name and name not in table_names:
                    table_names.append(name)

    return table_names

def rewrite_sql(sql, table_names):
    """Rewrite SQL to backtick-quote table names."""
    tokens = tokenize_sql(sql)
    result = []

    for tok, is_ws in tokens:
        if is_ws:
            result.append(tok)
        elif tok.startswith('`'):
            # Already quoted
            result.append(tok)
        elif tok in table_names:
            result.append(f'`{tok}`')
        else:
            result.append(tok)

    return ''.join(result)

# ============================================================
# Open file with optional compression
# ============================================================

def open_input_file(filename, compression=None):
    """Open a file for reading, handling compression."""
    if filename == '-':
        return sys.stdin

    # Detect compression from extension if not specified
    ext = os.path.splitext(filename)[1].lower()
    if compression is None:
        if ext == '.gz':
            compression = 'gz'
        elif ext == '.bz2':
            compression = 'bz2'
        elif ext in ('.zst', '.zstd'):
            compression = 'zstd'
        elif ext == '.lz4':
            compression = 'lz4'
        elif ext == '.xz':
            compression = 'xz'

    if compression == 'gz':
        return gzip.open(filename, 'rt', encoding='utf-8')
    elif compression == 'bz2':
        return bz2.open(filename, 'rt', encoding='utf-8')
    elif compression == 'xz':
        return lzma.open(filename, 'rt', encoding='utf-8')
    elif compression == 'zstd':
        import zstandard
        with open(filename, 'rb') as fh:
            dctx = zstandard.ZstdDecompressor()
            return io.TextIOWrapper(dctx.stream_reader(fh))
    elif compression == 'lz4':
        import lz4.frame
        return lz4.frame.open(filename, 'rt')
    else:
        return open(filename, 'r', encoding='utf-8', errors='replace', newline='')

def open_output_file(filename, compression=None):
    """Open a file for writing, handling compression."""
    ext = os.path.splitext(filename)[1].lower()
    if compression is None:
        if ext == '.gz':
            compression = 'gz'
        elif ext == '.bz2':
            compression = 'bz2'
        elif ext in ('.zst', '.zstd'):
            compression = 'zstd'
        elif ext == '.lz4':
            compression = 'lz4'
        elif ext == '.xz':
            compression = 'xz'

    if compression == 'gz':
        return gzip.open(filename, 'wt', encoding='utf-8')
    elif compression == 'bz2':
        return bz2.open(filename, 'wt', encoding='utf-8')
    elif compression == 'xz':
        return lzma.open(filename, 'wt', encoding='utf-8')
    else:
        return open(filename, 'w', encoding='utf-8')

# ============================================================
# Config file support
# ============================================================

def load_config(config_path=None):
    """Load configuration file."""
    if config_path is None:
        # Try default locations
        home = os.path.expanduser('~')
        candidates = [
            os.path.join(home, '.config', 'trdsql', 'config.json'),
            os.path.join(home, '.trdsql', 'config.json'),
        ]
        for path in candidates:
            if os.path.exists(path):
                config_path = path
                break
        else:
            return None, None

    try:
        with open(config_path) as f:
            config = json.load(f)
        return config, config_path
    except FileNotFoundError:
        return None, config_path
    except json.JSONDecodeError as e:
        raise ValueError(f"[{config_path}]config error: {e}")

# ============================================================
# Main processing
# ============================================================

def read_table(filename, fmt, args, jq_expr=None):
    """Read a table from a file. Returns (columns, rows)."""
    # Handle :: syntax for JSON path
    table_jq = jq_expr
    actual_file = filename
    if '::' in filename:
        parts = filename.split('::', 1)
        actual_file = parts[0]
        table_jq = parts[1]

    delimiter = args.id
    if delimiter == '\\t':
        delimiter = '\t'

    kwargs = dict(
        limit=args.ilr,
        null_values=args.inull if args.inull else None,
        add_num=args.inum,
    )

    try:
        f = open_input_file(actual_file)
    except FileNotFoundError:
        log_error(f"open {actual_file}: no such file or directory")
        return None, None
    except Exception as e:
        log_error(f"open {actual_file}: {e}")
        return None, None

    try:
        if fmt == 'csv':
            return read_csv(f, delimiter=delimiter, has_header=args.ih, 
                           skip=args.is_, preread=args.ir, **kwargs)
        elif fmt == 'ltsv':
            return read_ltsv(f, **kwargs)
        elif fmt == 'json':
            return read_json(f, jq_expr=table_jq, preread=args.ir, **kwargs)
        elif fmt == 'yaml':
            return read_yaml(f, **kwargs)
        elif fmt == 'tbln':
            return read_tbln(f, **kwargs)
        elif fmt == 'text':
            return read_text(f, **kwargs)
        elif fmt == 'width':
            return read_width(f, **kwargs)
        else:
            return read_csv(f, delimiter=delimiter, has_header=args.ih,
                           skip=args.is_, preread=args.ir, **kwargs)
    except Exception as e:
        log_error(f"import: {e}")
        return None, None
    finally:
        if f != sys.stdin:
            f.close()

def get_input_format(filename, args):
    """Determine input format for a file."""
    if args.icsv:
        return 'csv'
    elif args.ijson:
        return 'json'
    elif args.iltsv:
        return 'ltsv'
    elif args.itbln:
        return 'tbln'
    elif args.itext:
        return 'text'
    elif args.iwidth:
        return 'width'
    elif args.iyaml:
        return 'yaml'
    else:
        # Guess from extension
        return guess_format(filename)

def execute_query(sql, args, debug=False):
    """Execute the SQL query and return (columns, rows)."""
    # Find table names in SQL
    table_names = find_table_names(sql)

    if debug:
        # Print tokenized SQL
        tokens = tokenize_sql(sql)
        tok_str = ''.join(f'[{t}]' for t, _ in tokens)
        log_error(tok_str)

    # Create in-memory SQLite database
    conn = sqlite3.connect(':memory:')
    conn.row_factory = sqlite3.Row

    loaded_tables = set()

    # Load each table
    for table_name in table_names:
        if table_name in loaded_tables:
            continue

        # Check if it's a real file or subquery artifact
        actual_file = table_name.split('::')[0] if '::' in table_name else table_name

        fmt = get_input_format(actual_file, args)

        if debug:
            if fmt == 'csv' and not any([args.icsv, args.ijson, args.iltsv, args.itbln, args.itext, args.iwidth, args.iyaml]):
                log_error(f"Guess file type as CSV: [{actual_file}]")
            elif fmt == 'json':
                log_error(f"Guess file type as JSON: [{actual_file}]")
            elif fmt == 'ltsv':
                log_error(f"Guess file type as LTSV: [{actual_file}]")
            elif fmt == 'yaml':
                log_error(f"Guess file type as YAML: [{actual_file}]")
            elif fmt == 'tbln':
                log_error(f"Guess file type as TBLN: [{actual_file}]")

        jq_expr = None
        if args.ijq:
            jq_expr = args.ijq

        columns, rows = read_table(table_name, fmt, args, jq_expr=jq_expr)

        if columns is None:
            # File not found - continue, let SQLite error handle it
            loaded_tables.add(table_name)
            continue

        if debug:
            log_error(f"Column Names: [{','.join(columns)}]")
            log_error(f"Column Types: [{','.join(['text'] * len(columns))}]")

        # Create temporary table
        safe_cols = [f'`{c}`' for c in columns]
        col_defs = ', '.join(f'{c} text' for c in safe_cols)
        create_sql = f'CREATE TEMPORARY TABLE `{table_name}` ( {col_defs} );'

        if debug:
            log_error(create_sql)

        try:
            conn.execute(create_sql)
        except sqlite3.Error as e:
            log_error(f"create table: {e}")
            conn.close()
            return None, None

        if rows:
            # Insert data in batches
            ncols = len(columns)
            placeholders = ','.join(['?'] * ncols)
            insert_sql = f'INSERT INTO `{table_name}` ({", ".join(safe_cols)}) VALUES ({placeholders});'

            if debug:
                log_error(insert_sql)

            # Insert first row
            if rows:
                try:
                    # Batch insert
                    if len(rows) == 1:
                        conn.execute(insert_sql, rows[0])
                        if debug:
                            log_error(insert_sql)
                    else:
                        # Insert first row alone, then batch rest
                        conn.execute(insert_sql, rows[0])

                        # Batch remaining
                        if len(rows) > 1:
                            batch_placeholders = ','.join([f'({placeholders})'] * (len(rows) - 1))
                            batch_sql = f'INSERT INTO `{table_name}` ({", ".join(safe_cols)}) VALUES {batch_placeholders};'
                            flat = []
                            for r in rows[1:]:
                                flat.extend(r)
                            conn.execute(batch_sql, flat)
                            if debug:
                                log_error(batch_sql)
                except sqlite3.Error as e:
                    log_error(f"insert: {e}")

            conn.commit()

        loaded_tables.add(table_name)

    # Rewrite SQL with backtick-quoted table names
    modified_sql = rewrite_sql(sql, [t for t in table_names if t in loaded_tables or True])

    if debug:
        log_error(modified_sql)

    # Execute the query
    try:
        cursor = conn.execute(modified_sql)
        result_columns = [desc[0] for desc in cursor.description] if cursor.description else []
        result_rows = cursor.fetchall()
        result_rows = [list(row) for row in result_rows]
        conn.close()
        return result_columns, result_rows
    except sqlite3.Error as e:
        log_error(f"export: {e} [{modified_sql}]")
        conn.close()
        return None, None

def output_result(columns, rows, args, out_file=None):
    """Output results in the specified format."""
    fmt = 'csv'  # default

    if args.ocsv:
        fmt = 'csv'
    elif args.ojson:
        fmt = 'json'
    elif args.ojsonl:
        fmt = 'jsonl'
    elif args.oltsv:
        fmt = 'ltsv'
    elif args.oat:
        fmt = 'at'
    elif args.omd:
        fmt = 'md'
    elif args.oyaml:
        fmt = 'yaml'
    elif args.otbln:
        fmt = 'tbln'
    elif args.ovf:
        fmt = 'vf'
    elif args.oraw:
        fmt = 'raw'

    null_value = args.onull if args.onull is not None else ''
    delimiter = args.od
    if delimiter == '\\t':
        delimiter = '\t'

    if fmt == 'csv':
        output = format_csv(rows, columns, delimiter=delimiter, 
                            quote_char=args.oq, quote_all=args.oaq,
                            header=args.oh, crlf=args.ocrlf, null_value=null_value)
    elif fmt == 'raw':
        output = format_raw(rows, columns, delimiter=delimiter,
                            header=args.oh, crlf=args.ocrlf, null_value=null_value)
    elif fmt == 'json':
        output = format_json(rows, columns, null_value=null_value)
    elif fmt == 'jsonl':
        output = format_jsonl(rows, columns, null_value=null_value)
    elif fmt == 'ltsv':
        output = format_ltsv(rows, columns, null_value=null_value, crlf=args.ocrlf)
    elif fmt == 'at':
        output = format_at(rows, columns, null_value=null_value, 
                           nowrap=args.onowrap, crlf=args.ocrlf)
    elif fmt == 'md':
        output = format_md(rows, columns, null_value=null_value,
                           nowrap=args.onowrap, crlf=args.ocrlf)
    elif fmt == 'yaml':
        output = format_yaml(rows, columns, null_value=null_value)
    elif fmt == 'tbln':
        output = format_tbln(rows, columns, null_value=null_value, crlf=args.ocrlf)
    elif fmt == 'vf':
        output = format_vf(rows, columns, null_value=null_value, crlf=args.ocrlf)
    else:
        output = format_csv(rows, columns, delimiter=delimiter,
                            quote_char=args.oq, quote_all=args.oaq,
                            header=args.oh, crlf=args.ocrlf, null_value=null_value)

    if out_file:
        out_file.write(output)
    else:
        sys.stdout.write(output)

def do_analyze(filename, args, only_suggest=False):
    """Analyze a file and suggest SQL."""
    fmt = get_input_format(filename, args)

    columns, rows = read_table(filename, fmt, args)
    if columns is None:
        return 1

    sample_rows = rows[:1]

    # Build option string for the suggest
    opts = []
    if args.ih:
        opts.append('-ih')

    opts_str = ' '.join(opts) + ' ' if opts else ''

    if not only_suggest:
        print(f"The table name is {filename}.")

        fmt_name = fmt.upper()
        if fmt == 'csv':
            fmt_name = 'CSV'
        elif fmt == 'json':
            fmt_name = 'JSON'
        elif fmt == 'ltsv':
            fmt_name = 'LTSV'
        elif fmt == 'yaml':
            fmt_name = 'YAML'
        elif fmt == 'tbln':
            fmt_name = 'TBLN'
        print(f"The file type is {fmt_name}.")
        print()
        print("Data types:")

        # Print type table
        type_rows = [[c, 'text'] for c in columns]
        type_cols = ['column name', 'type']
        print(format_at(type_rows, type_cols), end='')
        print()
        print("Data samples:")
        print(format_at(sample_rows, columns), end='')
        print()
        print("Examples:")

    col_list = ', '.join(columns)
    exe = sys.argv[0]

    print(f'{exe} {opts_str}"SELECT {col_list} FROM {filename}"')

    if sample_rows and columns:
        first_col = columns[0]
        first_val = sample_rows[0][0] if sample_rows[0] else ''
        print(f'{exe} {opts_str}"SELECT {col_list} FROM {filename} WHERE {first_col} = \'{first_val}\'"')

    print(f'{exe} {opts_str}"SELECT {columns[0]}, count({columns[0]}) FROM {filename} GROUP BY {columns[0]}"')
    print(f'{exe} {opts_str}"SELECT {col_list} FROM {filename} ORDER BY {columns[0]} LIMIT 10"')

    return 0

def print_usage():
    """Print usage information."""
