    elif args.db:
        log_error(f"ERROR: db[{args.db}] does not found")

    if args.debug:
        log_error(f"driver: {driver}, dsn: {dsn}")

    # Handle -a (analyze)
    if args.a:
        return do_analyze(args.a, args, only_suggest=False)

    # Handle -A (only suggest)
    if args.A:
        return do_analyze(args.A, args, only_suggest=True)

    # Get SQL
    sql = None

    if args.q:
        try:
            with open(args.q) as f:
                sql = f.read().strip()
        except FileNotFoundError:
            log_error(f"open {args.q}: no such file or directory")
            return 1
    elif args.t:
        # Table mode - just SELECT * FROM table
        sql = f"SELECT * FROM {args.t}"
    elif args.sql:
        sql = args.sql
    else:
        # No SQL provided - show usage
        print_usage()
        return 2

    # Execute query
    columns, rows = execute_query(sql, args, debug=args.debug)

    if columns is None:
        return 1

    # Output
    out_file = None
    if args.out:
        try:
            out_file = open_output_file(args.out, args.oz)
        except Exception as e:
            log_error(f"open output: {e}")
            return 1

    try:
        output_result(columns, rows, args, out_file=out_file)
    finally:
        if out_file:
            out_file.close()

    return 0


