            if ':' in rest and not rest.startswith('"') and not rest.startswith("'"):
                colon_pos = rest.index(':')
                k = rest[:colon_pos].strip()
                v = rest[colon_pos+1:].strip()
                current_obj = OrderedDict()
                result.append(current_obj)
                current_obj[k] = parse_yaml_value(v)
            elif rest:
                result.append(parse_yaml_value(rest))
                current_obj = None
            else:
                current_obj = OrderedDict()
                result.append(current_obj)
        elif stripped == '-':
            current_obj = OrderedDict()
            result.append(current_obj)
        elif ':' in stripped and current_obj is not None:
            indent = len(line) - len(line.lstrip())
            if indent > 0:
                colon_pos = stripped.index(':')
                k = stripped[:colon_pos].strip()
                v = stripped[colon_pos+1:].strip()
                current_obj[k] = parse_yaml_value(v)

    return result


def read_yaml(f, limit=0, null_values=None, add_num=False):
    """Read YAML format. Returns (columns, rows)."""
    content = f.read()
    if isinstance(content, bytes):
        content = content.decode('utf-8')

    data = parse_simple_yaml(content)
    columns, rows = _json_to_rows(data)

    if limit > 0:
        rows = rows[:limit]

    if null_values:
        rows = [
            [None if cell in null_values else cell for cell in row]
            for row in rows
        ]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i + 1)] + row for i, row in enumerate(rows)]

    return columns, rows


def read_tbln(f, limit=0, null_values=None, add_num=False):
    """Read TBLN format. Returns (columns, rows)."""
    columns = None
    rows = []

    for line in f:
        if isinstance(line, bytes):
            line = line.decode('utf-8')
        line = line.rstrip('\n\r')

        if line.startswith(';'):
            m = re.match(r';\s*name:\s*\|(.*)\|', line)
            if m:
                parts = m.group(1).split('|')
                columns = [p.strip() for p in parts]
        elif line.startswith('|'):
            parts = line.split('|')
            parts = parts[1:-1]  # Remove leading/trailing empty
            row = [p.strip() for p in parts]
            rows.append(row)
            if limit > 0 and len(rows) >= limit:
                break

    if columns is None:
        columns = [f'c{i+1}' for i in range(len(rows[0]))] if rows else []

    if null_values:
        rows = [
            [None if cell in null_values else cell for cell in row]
            for row in rows
        ]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i + 1)] + row for i, row in enumerate(rows)]

    return columns, rows


def read_text(f, limit=0, null_values=None, add_num=False):
    """Read text format (one line per row). Returns (columns, rows)."""
    columns = ['text']
    rows = []
    for line in f:
        if isinstance(line, bytes):
            line = line.decode('utf-8')
        line = line.rstrip('\n\r')
        rows.append([line])
        if limit > 0 and len(rows) >= limit:
            break

    if null_values:
        rows = [
            [None if cell in null_values else cell for cell in row]
            for row in rows
        ]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i + 1)] + row for i, row in enumerate(rows)]

    return columns, rows


def read_width(f, limit=0, null_values=None, add_num=False):
    """Read fixed-width format. Returns (columns, rows)."""
    lines = []
    for line in f:
        if isinstance(line, bytes):
            line = line.decode('utf-8')
        line = line.rstrip('\n\r')
        lines.append(line)

    if not lines:
        return [], []

    # Parse header line to get column boundaries
    header_line = lines[0]
    col_starts = []
    col_names = []

    i = 0
    while i < len(header_line):
        if header_line[i] != ' ':
            j = i
            while j < len(header_line) and header_line[j] != ' ':
                j += 1
            col_starts.append(i)
            col_names.append(header_line[i:j].strip())
            i = j
        else:
            i += 1

    columns = col_names
    rows = []

    for line in lines[1:]:
        row = []
        for idx, start in enumerate(col_starts):
            if idx + 1 < len(col_starts):
                end = col_starts[idx + 1]
                val = line[start:end].strip() if start < len(line) else ''
            else:
                val = line[start:].strip() if start < len(line) else ''
            row.append(val)
        rows.append(row)
        if limit > 0 and len(rows) >= limit:
            break

    if null_values:
        rows = [
            [None if cell in null_values else cell for cell in row]
            for row in rows
        ]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i + 1)] + row for i, row in enumerate(rows)]

    return columns, rows


# ============================================================
# Format detection
# ============================================================

def guess_format_from_ext(filename):
    """Guess format from filename extension."""
    if filename == '-':
        return 'csv'

    base = filename.split('::')[0]
    name = base

    # Strip compression extensions
    for ext in ('.gz', '.bz2', '.zst', '.zstd', '.lz4', '.xz'):
        if name.lower().endswith(ext):
            name = name[:-len(ext)]
            break

    ext = os.path.splitext(name)[1].lower()
    fmt_map = {
        '.csv': 'csv',
        '.tsv': 'csv',
        '.ltsv': 'ltsv',
        '.json': 'json',
        '.jsonl': 'json',
        '.ndjson': 'json',
        '.yaml': 'yaml',
        '.yml': 'yaml',
        '.tbln': 'tbln',
    }
    return fmt_map.get(ext, None)


def get_input_format(filename, args):
    """Determine input format."""
    if args.icsv:
        return 'csv'
    elif args.ijson:
        return 'json'
    elif args.iltsv:
        return 'ltsv'
    elif args.itbln:
        return 'tbln'
    elif args.itext:
        return 'text'
    elif args.iwidth:
        return 'width'
    elif args.iyaml:
        return 'yaml'
    else:
        guessed = guess_format_from_ext(filename)
        if guessed:
            return guessed
        # Default to CSV for unknown extensions
        return 'csv'


# ============================================================
# File I/O
# ============================================================

def open_input_file(filename):
    """Open a file for reading with automatic decompression."""
    if filename == '-':
        return sys.stdin

    ext = os.path.splitext(filename)[1].lower()
    if ext == '.gz':
        return gzip.open(filename, 'rt', encoding='utf-8', errors='replace')
    elif ext == '.bz2':
        return bz2.open(filename, 'rt', encoding='utf-8', errors='replace')
    elif ext in ('.xz', '.lzma'):
        return lzma.open(filename, 'rt', encoding='utf-8', errors='replace')
    else:
        return open(filename, 'r', encoding='utf-8', errors='replace', newline='')


def open_output_file(filename, compression=None):
    """Open a file for writing with optional compression."""
    ext = os.path.splitext(filename)[1].lower()
    comp = compression
    if comp is None:
        if ext == '.gz':
            comp = 'gz'
        elif ext == '.bz2':
            comp = 'bz2'
        elif ext in ('.xz', '.lzma'):
            comp = 'xz'
        elif ext in ('.zst', '.zstd'):
            comp = 'zstd'
        elif ext == '.lz4':
            comp = 'lz4'

    if comp == 'gz':
        return gzip.open(filename, 'wt', encoding='utf-8')
    elif comp == 'bz2':
        return bz2.open(filename, 'wt', encoding='utf-8')
    elif comp == 'xz':
        return lzma.open(filename, 'wt', encoding='utf-8')
    else:
        return open(filename, 'w', encoding='utf-8')


# ============================================================
# Output formatters
# ============================================================

def format_csv(rows, columns, delimiter=',', quote_char='"', quote_all=False,
               header=False, crlf=False, null_value=''):
    """Format as CSV."""
    output = io.StringIO()
    quoting = csv.QUOTE_ALL if quote_all else csv.QUOTE_MINIMAL
    writer = csv.writer(output, delimiter=delimiter, quotechar=quote_char,
                        quoting=quoting, lineterminator='\r\n' if crlf else '\n')
    if header:
        writer.writerow(columns)
    for row in rows:
        processed = [null_value if v is None else (v if v is not None else '') for v in row]
        writer.writerow(processed)
    return output.getvalue()


def format_raw(rows, columns, delimiter=',', header=False, crlf=False, null_value=''):
    """Format as raw (no quoting)."""
    lines = []
    if header:
        lines.append(delimiter.join(str(c) for c in columns))
    for row in rows:
        processed = [null_value if v is None else str(v) for v in row]
        lines.append(delimiter.join(processed))
    sep = '\r\n' if crlf else '\n'
    if lines:
        return sep.join(lines) + sep
    return ''


def format_json_out(rows, columns, null_value=''):
    """Format as JSON array."""
    result = []
    for row in rows:
        obj = OrderedDict()
        for i, col in enumerate(columns):
            v = row[i] if i < len(row) else ''
            if v is None:
                obj[col] = null_value if null_value else None
            else:
                obj[col] = v
        result.append(obj)
    return json.dumps(result, indent=2, ensure_ascii=False) + '\n'


def format_jsonl_out(rows, columns, null_value=''):
    """Format as JSON Lines."""
    lines = []
    for row in rows:
        obj = OrderedDict()
        for i, col in enumerate(columns):
            v = row[i] if i < len(row) else ''
            if v is None:
                obj[col] = null_value if null_value else None
            else:
                obj[col] = v
        lines.append(json.dumps(obj, ensure_ascii=False))
    return '\n'.join(lines) + '\n' if lines else ''


def format_ltsv_out(rows, columns, null_value='', crlf=False):
    """Format as LTSV."""
    lines = []
    for row in rows:
        parts = []
        for i, col in enumerate(columns):
            v = row[i] if i < len(row) else ''
            if v is None:
                v = null_value
            parts.append(f"{col}:{v}")
        lines.append('\t'.join(parts))
    sep = '\r\n' if crlf else '\n'
    return sep.join(lines) + sep if lines else ''


def format_yaml_out(rows, columns, null_value=''):
    """Format as YAML list of objects."""
    lines = []
    for row in rows:
        first = True
        for i, col in enumerate(columns):
            v = row[i] if i < len(row) else ''
            if v is None:
                v = null_value if null_value else None

            prefix = '- ' if first else '  '
            first = False

            if v is None:
                lines.append(f"{prefix}{col}: null")
            else:
                lines.append(f"{prefix}{col}: {v}")
    return '\n'.join(lines) + '\n' if lines else ''


def format_tbln_out(rows, columns, null_value='', crlf=False):
    """Format as TBLN."""
    lines = []
    names = ' | '.join(columns)
    lines.append(f"; name: | {names} |")
    types = ' | '.join(['text'] * len(columns))
    lines.append(f"; type: | {types} |")
    for row in rows:
        parts = []
        for i in range(len(columns)):
            v = row[i] if i < len(row) else ''
            if v is None:
                v = null_value
            parts.append(f" {v} ")
        lines.append('|' + '|'.join(parts) + '|')
    sep = '\r\n' if crlf else '\n'
    return sep.join(lines) + sep if lines else ''


def format_vf_out(rows, columns, null_value='', crlf=False):
    """Format as vertical format."""
    max_col_len = max((len(c) for c in columns), default=0)
    lines = []
    for i, row in enumerate(rows):
        lines.append(f"---[{i+1:2d}]------------------------")
        for j, col in enumerate(columns):
            v = row[j] if j < len(row) else ''
            if v is None:
                v = null_value
            lines.append(f"{col:>{max_col_len}} | {v}")
    sep = '\r\n' if crlf else '\n'
    return sep.join(lines) + sep if lines else ''


def _calc_col_widths(rows, columns):
    """Calculate column widths for table formatting."""
    widths = [len(str(c)) for c in columns]
    for row in rows:
        for i, v in enumerate(row):
            if i < len(widths):
                vstr = '' if v is None else str(v)
                widths[i] = max(widths[i], len(vstr))
    return widths


def format_at_out(rows, columns, null_value='', nowrap=False, crlf=False):
    """Format as ASCII Table."""
    widths = _calc_col_widths(rows, columns)
    sep = '\r\n' if crlf else '\n'
    lines = []

    border = '+' + '+'.join('-' * (w + 2) for w in widths) + '+'
    lines.append(border)

    header_parts = [' ' + str(col).center(w) + ' ' for col, w in zip(columns, widths)]
    lines.append('|' + '|'.join(header_parts) + '|')
    lines.append(border)

    for row in rows:
        parts = []
        for i, w in enumerate(widths):
            v = row[i] if i < len(row) else ''
            vstr = null_value if v is None else str(v) if v is not None else ''
            if is_numeric(vstr):
                parts.append(' ' + vstr.rjust(w) + ' ')
            else:
                parts.append(' ' + vstr.ljust(w) + ' ')
        lines.append('|' + '|'.join(parts) + '|')

    lines.append(border)
    return sep.join(lines) + sep


def format_md_out(rows, columns, null_value='', nowrap=False, crlf=False):
    """Format as Markdown table."""
    widths = _calc_col_widths(rows, columns)
    sep = '\r\n' if crlf else '\n'
    lines = []

    header_parts = [' ' + str(col).center(w) + ' ' for col, w in zip(columns, widths)]
    lines.append('|' + '|'.join(header_parts) + '|')

    sep_parts = ['-' * (w + 2) for w in widths]
    lines.append('|' + '|'.join(sep_parts) + '|')

    for row in rows:
        parts = []
        for i, w in enumerate(widths):
            v = row[i] if i < len(row) else ''
            vstr = null_value if v is None else str(v) if v is not None else ''
            if is_numeric(vstr):
                parts.append(' ' + vstr.rjust(w) + ' ')
            else:
                parts.append(' ' + vstr.ljust(w) + ' ')
        lines.append('|' + '|'.join(parts) + '|')

    return sep.join(lines) + sep if lines else ''


def output_result(columns, rows, args, out_file=None):
    """Output results in the specified format."""
    null_value = args.onull if args.onull is not None else ''
    delimiter = args.od
    if delimiter == '\\t':
        delimiter = '\t'

    # Determine output format
    if args.ojson:
        output = format_json_out(rows, columns, null_value=null_value)
    elif args.ojsonl:
        output = format_jsonl_out(rows, columns, null_value=null_value)
    elif args.oltsv:
        output = format_ltsv_out(rows, columns, null_value=null_value, crlf=args.ocrlf)
    elif args.oat:
        output = format_at_out(rows, columns, null_value=null_value,
                               nowrap=args.onowrap, crlf=args.ocrlf)
    elif args.omd:
        output = format_md_out(rows, columns, null_value=null_value,
                               nowrap=args.onowrap, crlf=args.ocrlf)
    elif args.oyaml:
        output = format_yaml_out(rows, columns, null_value=null_value)
    elif args.otbln:
        output = format_tbln_out(rows, columns, null_value=null_value, crlf=args.ocrlf)
    elif args.ovf:
        output = format_vf_out(rows, columns, null_value=null_value, crlf=args.ocrlf)
    elif args.oraw:
        output = format_raw(rows, columns, delimiter=delimiter,
                            header=args.oh, crlf=args.ocrlf, null_value=null_value)
    else:
        # Default: CSV
        output = format_csv(rows, columns, delimiter=delimiter,
                            quote_char=args.oq, quote_all=args.oaq,
                            header=args.oh, crlf=args.ocrlf, null_value=null_value)

    writer = out_file if out_file else sys.stdout
    writer.write(output)


# ============================================================
# Table loading
# ============================================================

def read_table(table_name, fmt, args):
    """Load a table from file. Returns (columns, rows) or (None, None) on error."""
    actual_file = table_name
    jq_expr = None

    if '::' in table_name:
        parts = table_name.split('::', 1)
        actual_file = parts[0]
        jq_expr = parts[1]

    # Override jq_expr from command line
    if args.ijq:
        jq_expr = args.ijq

    delimiter = args.id
    if delimiter == '\\t':
        delimiter = '\t'

    kwargs = dict(
        limit=args.ilr,
        null_values=args.inull if args.inull else None,
        add_num=args.inum,
    )

    try:
        f = open_input_file(actual_file)
    except FileNotFoundError:
        log_error(f"open {actual_file}: no such file or directory")
        return None, None
    except IsADirectoryError:
        log_error(f"open {actual_file}: Is a directory")
        return None, None
    except Exception as e:
        log_error(f"open {actual_file}: {e}")
        return None, None

    try:
        if fmt == 'csv':
            return read_csv(f, delimiter=delimiter, has_header=args.ih,
                            skip=args.is_, preread=args.ir, **kwargs)
        elif fmt == 'ltsv':
            return read_ltsv(f, **kwargs)
        elif fmt == 'json':
            return read_json(f, jq_expr=jq_expr, preread=args.ir, **kwargs)
        elif fmt == 'yaml':
            return read_yaml(f, **kwargs)
        elif fmt == 'tbln':
            return read_tbln(f, **kwargs)
        elif fmt == 'text':
            return read_text(f, **kwargs)
        elif fmt == 'width':
            return read_width(f, **kwargs)
        else:
            return read_csv(f, delimiter=delimiter, has_header=args.ih,
                            skip=args.is_, preread=args.ir, **kwargs)
    except ValueError as e:
        log_error(f"import: {e}")
        return None, None
    except Exception as e:
        log_error(f"import: {e}")
        return None, None
    finally:
        if f is not sys.stdin:
            try:
                f.close()
            except Exception:
                pass


# ============================================================
# Query execution
# ============================================================

def execute_query(sql, args, debug=False):
    """Execute SQL query. Returns (columns, rows) or (None, None)."""
    table_names = find_table_names(sql)

    if debug:
        tokens = tokenize_sql(sql)
        tok_str = ''.join(f'[{t}]' for t, _ in tokens)
        log_error(tok_str)

    conn = sqlite3.connect(':memory:')

    loaded_tables = set()
    failed_tables = set()

    for table_name in table_names:
        if table_name in loaded_tables or table_name in failed_tables:
            continue

        actual_file = table_name.split('::')[0] if '::' in table_name else table_name
        fmt = get_input_format(actual_file, args)

        if debug:
            explicit_fmt = any([args.icsv, args.ijson, args.iltsv, args.itbln,
                                args.itext, args.iwidth, args.iyaml])
            if not explicit_fmt:
                guessed = guess_format_from_ext(actual_file)
                if guessed:
                    fmt_name = {'csv': 'CSV', 'json': 'JSON', 'ltsv': 'LTSV',
                                'yaml': 'YAML', 'tbln': 'TBLN', 'text': 'text',
                                'width': 'width'}.get(fmt, fmt.upper())
                    log_error(f"Guess file type as {fmt_name}: [{actual_file}]")
                else:
                    log_error(f"Set in CSV because the extension is unknown: [{actual_file}]")
                    log_error(f"Guess file type as CSV: [{actual_file}]")

        columns, rows = read_table(table_name, fmt, args)

        if columns is None:
            failed_tables.add(table_name)
            continue

        if debug:
            log_error(f"Column Names: [{','.join(columns)}]")
            log_error(f"Column Types: [{','.join(['text'] * len(columns))}]")

        safe_cols = [f'`{c}`' for c in columns]
        col_defs = ', '.join(f'{c} text' for c in safe_cols)
        create_sql = f'CREATE TEMPORARY TABLE `{table_name}` ( {col_defs} );'

        if debug:
            log_error(create_sql)

        try:
            conn.execute(create_sql)
        except sqlite3.Error as e:
            log_error(f"create table: {e}")
            conn.close()
            return None, None

        if rows:
            ncols = len(columns)
            placeholders = ','.join(['?'] * ncols)
            col_list = ', '.join(safe_cols)
            insert_sql = f'INSERT INTO `{table_name}` ({col_list}) VALUES ({placeholders});'

            if debug:
                log_error(insert_sql)

            # Insert first row individually, then batch the rest
            try:
                conn.execute(insert_sql, rows[0])
                if len(rows) > 1:
                    batch_ph = ','.join([f'({placeholders})'] * (len(rows) - 1))
                    batch_sql = f'INSERT INTO `{table_name}` ({col_list}) VALUES {batch_ph};'
                    flat = [v for r in rows[1:] for v in r]
                    conn.execute(batch_sql, flat)
                    if debug:
                        log_error(batch_sql)
            except sqlite3.Error as e:
                log_error(f"insert: {e}")

            conn.commit()

        loaded_tables.add(table_name)

    # Rewrite SQL with backtick-quoted table names
    all_known = list(loaded_tables) + list(failed_tables)
    modified_sql = rewrite_sql(sql, all_known)

    if debug:
        log_error(modified_sql)

    try:
        cursor = conn.execute(modified_sql)
        result_columns = [desc[0] for desc in cursor.description] if cursor.description else []
        result_rows = [list(row) for row in cursor.fetchall()]
        conn.close()
        return result_columns, result_rows
    except sqlite3.Error as e:
        log_error(f"export: {e} [{modified_sql}]")
        conn.close()
        return None, None


# ============================================================
# Analyze mode
# ============================================================

def do_analyze(filename, args, only_suggest=False):
    """Analyze file and suggest SQL queries."""
    fmt = get_input_format(filename, args)
    columns, rows = read_table(filename, fmt, args)

    if columns is None:
        return 1

    sample_rows = rows[:1]

    # Build option string
    opts = []
    if args.ih:
        opts.append('-ih')
    opts_str = (' '.join(opts) + ' ') if opts else ''

    exe = sys.argv[0]

    if not only_suggest:
        fmt_name = {'csv': 'CSV', 'json': 'JSON', 'ltsv': 'LTSV',
                    'yaml': 'YAML', 'tbln': 'TBLN', 'text': 'text',
                    'width': 'width'}.get(fmt, fmt.upper())

        print(f"The table name is {filename}.")
        print(f"The file type is {fmt_name}.")
        print()
        print("Data types:")
        type_rows = [[c, 'text'] for c in columns]
        print(format_at_out(type_rows, ['column name', 'type']), end='')
        print()
        print("Data samples:")
        print(format_at_out(sample_rows, columns), end='')
        print()
        print("Examples:")

    col_list = ', '.join(columns)
    print(f'{exe} {opts_str}"SELECT {col_list} FROM {filename}"')

    if sample_rows and columns:
        first_col = columns[0]
        first_val = sample_rows[0][0] if sample_rows[0] else ''
        print(f'{exe} {opts_str}"SELECT {col_list} FROM {filename} WHERE {first_col} = \'{first_val}\'"')

    print(f'{exe} {opts_str}"SELECT {columns[0]}, count({columns[0]}) FROM {filename} GROUP BY {columns[0]}"')
    print(f'{exe} {opts_str}"SELECT {col_list} FROM {filename} ORDER BY {columns[0]} LIMIT 10"')

    return 0


# ============================================================
# Config loading
# ============================================================

def load_config(config_path=None):
    """Load config file. Returns (config_dict, path_tried)."""
    if config_path is None:
        home = os.path.expanduser('~')
        default = os.path.join(home, '.config', 'trdsql', 'config.json')
        if os.path.exists(default):
            config_path = default
        else:
            return None, default

    try:
        with open(config_path) as f:
            config = json.load(f)
        return config, config_path
    except FileNotFoundError:
        return None, config_path
    except json.JSONDecodeError as e:
        raise ValueError(f"[{config_path}]config error: {e}")


