    return bool(re.match(r'^-?[0-9]+(\.[0-9]+)?$', s))


# ============================================================
# SQL Tokenizer
# ============================================================

def tokenize_sql(sql):
    """Tokenize SQL. Returns list of (token_str, is_whitespace) tuples.
    Separators: whitespace, comma, =, (, ), ; and quoted strings."""
    tokens = []
    i = 0
    while i < len(sql):
        c = sql[i]

        if c in (' ', '\t', '\n', '\r'):
            j = i
            while j < len(sql) and sql[j] in (' ', '\t', '\n', '\r'):
                j += 1
            tokens.append((' ', True))
            i = j
        elif c == "'":
            # Single-quoted string
            j = i + 1
            while j < len(sql):
                if sql[j] == "'" and (j + 1 >= len(sql) or sql[j+1] != "'"):
                    j += 1
                    break
                elif sql[j] == "'" and j + 1 < len(sql) and sql[j+1] == "'":
                    j += 2
                else:
                    j += 1
            tokens.append((sql[i:j], False))
            i = j
        elif c == '"':
            # Double-quoted string
            j = i + 1
            while j < len(sql):
                if sql[j] == '"' and (j + 1 >= len(sql) or sql[j+1] != '"'):
                    j += 1
                    break
                elif sql[j] == '"' and j + 1 < len(sql) and sql[j+1] == '"':
                    j += 2
                else:
                    j += 1
            tokens.append((sql[i:j], False))
            i = j
        elif c == '`':
            # Backtick-quoted identifier
            j = i + 1
            while j < len(sql) and sql[j] != '`':
                j += 1
            if j < len(sql):
                j += 1
            tokens.append((sql[i:j], False))
            i = j
        elif c in (',', '=', '(', ')', ';'):
            tokens.append((c, False))
            i += 1
        else:
            # Regular token
            j = i
            while j < len(sql) and sql[j] not in (' ', '\t', '\n', '\r', ',', '=', '(', ')', ';', "'", '"', '`'):
                j += 1
            if j > i:
                tokens.append((sql[i:j], False))
            i = j if j > i else i + 1

    return tokens


def find_table_names(sql):
    """Find table names in SQL after FROM/JOIN/INTO/UPDATE/TABLE keywords."""
    tokens = tokenize_sql(sql)

    TABLE_KEYWORDS = {'from', 'join', 'into', 'update', 'table'}
    SKIP_KEYWORDS = {'select', 'with', 'where', 'set', 'on', 'as', 'and', 'or',
                     'not', 'in', 'between', 'like', 'is', 'null', 'order', 'group',
                     'by', 'having', 'limit', 'offset', 'union', 'intersect', 'except',
                     'distinct', 'all', 'inner', 'outer', 'left', 'right', 'full',
                     'cross', 'natural', 'using', 'case', 'when', 'then', 'else',
                     'end', 'exists', 'any', 'some', 'asc', 'desc', 'create',
                     'temporary', 'view', 'index', 'drop', 'alter', 'delete', 'insert'}

    # Get non-whitespace tokens
    nws = [t for t, is_ws in tokens if not is_ws]

    table_names = []
    i = 0
    while i < len(nws):
        tok = nws[i]
        if tok.lower() in TABLE_KEYWORDS:
            j = i + 1
            while j < len(nws):
                next_tok = nws[j]
                if next_tok == '(':
                    break  # Subquery
                if next_tok.lower() in SKIP_KEYWORDS:
                    break
                if next_tok in (',', '=', ')', ';'):
                    break

                # Check if it's backtick-quoted
                if next_tok.startswith('`') and next_tok.endswith('`'):
                    name = next_tok[1:-1]
                    if name and name not in table_names:
                        table_names.append(name)
                elif next_tok.startswith("'") or next_tok.startswith('"'):
                    # String literal - could be table name
                    name = next_tok[1:-1]
                    if name and name not in table_names:
                        table_names.append(name)
                else:
                    # Regular identifier
                    if next_tok not in table_names:
                        table_names.append(next_tok)
                break  # Only take first token after keyword
            i = j if j > i else i + 1
            continue
        i += 1

    # Handle comma-separated table lists: FROM a, b
    # Re-scan to handle: FROM t1, t2
    nws2 = [t for t, is_ws in tokens if not is_ws]
    i = 0
    while i < len(nws2):
        tok = nws2[i]
        if tok.lower() in TABLE_KEYWORDS:
            j = i + 1
            # Collect table names until non-table token
            while j < len(nws2):
                next_tok = nws2[j]
                if next_tok == '(':
                    break
                if next_tok == ',':
                    j += 1
                    continue
                if next_tok.lower() in SKIP_KEYWORDS:
                    break
                if next_tok in ('=', ')', ';'):
                    break

                # Process the table name
                name = next_tok
                if name.startswith('`') and name.endswith('`'):
                    name = name[1:-1]
                elif name.startswith("'") or name.startswith('"'):
                    name = name[1:-1]

                if name and name not in table_names:
                    table_names.append(name)

                # Check if next is comma (more tables) or alias
                k = j + 1
                if k < len(nws2):
                    nxt = nws2[k]
                    if nxt == ',':
                        j = k + 1
                        continue
                    elif nxt.lower() not in SKIP_KEYWORDS and nxt not in (',', '=', '(', ')', ';'):
                        # Could be an alias
                        j = k + 1
                        if j < len(nws2) and nws2[j] == ',':
                            j += 1
                            continue
                        break
                    else:
                        break
                break
        i += 1

    return list(dict.fromkeys(table_names))  # preserve order, dedupe


def rewrite_sql(sql, table_names):
    """Rewrite SQL to backtick-quote table names for SQLite."""
    if not table_names:
        return sql

    tokens = tokenize_sql(sql)
    result = []

    for tok, is_ws in tokens:
        if is_ws:
            result.append(tok)
        elif tok.startswith('`'):
            result.append(tok)
        elif tok in table_names:
            result.append(f'`{tok}`')
        elif tok.startswith("'") and tok[1:-1] in table_names:
            name = tok[1:-1]
            result.append(f'`{name}`')
        elif tok.startswith('"') and tok[1:-1] in table_names:
            name = tok[1:-1]
            result.append(f'`{name}`')
        else:
            result.append(tok)

    return ''.join(result)


