def read_csv(f, delimiter=',', has_header=False, skip=0, limit=0,
             preread=1, null_values=None, add_num=False):
    """Read CSV format. Returns (columns, rows)."""
    if delimiter == '\\t':
        delimiter = '\t'

    reader = csv.reader(f, delimiter=delimiter)
    rows_raw = []
    for row in reader:
        if row:  # skip empty rows
            rows_raw.append(row)

    # Skip header rows
    if skip > 0:
        rows_raw = rows_raw[skip:]

    if not rows_raw:
        return [], []

    # Determine columns
    if has_header and rows_raw:
        columns = rows_raw[0]
        data_rows = rows_raw[1:]
    else:
        max_cols = max((len(r) for r in rows_raw[:max(preread, 1)]), default=0)
        columns = [f'c{i+1}' for i in range(max_cols)]
        data_rows = rows_raw

    # Apply limit
    if limit > 0:
        data_rows = data_rows[:limit]

    # Process null values
    if null_values:
        data_rows = [
            [None if cell in null_values else cell for cell in row]
            for row in data_rows
        ]

    # Add row number column
    if add_num:
        columns = ['num'] + columns
        data_rows = [[str(i + 1)] + row for i, row in enumerate(data_rows)]

    # Pad/trim rows to column count
    ncols = len(columns)
    data_rows = [row[:ncols] + [''] * max(0, ncols - len(row)) for row in data_rows]

    return columns, data_rows


def read_ltsv(f, limit=0, null_values=None, add_num=False):
    """Read LTSV format. Returns (columns, rows)."""
    columns = None
    rows = []
    for line in f:
        if isinstance(line, bytes):
            line = line.decode('utf-8')
        line = line.rstrip('\n\r')
        if not line:
            continue
        fields = line.split('\t')
        record = OrderedDict()
        for field in fields:
            if ':' in field:
                k, v = field.split(':', 1)
                record[k] = v
            else:
                record[field] = ''
        if columns is None:
            columns = list(record.keys())
        rows.append([record.get(c, '') for c in columns])
        if limit > 0 and len(rows) >= limit:
            break

    if columns is None:
        columns = []

    if null_values:
        rows = [
            [None if cell in null_values else cell for cell in row]
            for row in rows
        ]

    if add_num:
        columns = ['num'] + columns
        rows = [[str(i + 1)] + row for i, row in enumerate(rows)]

    return columns, rows


def _apply_jq(data, jq_expr):
    """Apply a jq expression to data using the system jq binary."""
    proc = subprocess.run(
        ['jq', '-c', jq_expr],
        input=json.dumps(data).encode(),
        capture_output=True
    )
    if proc.returncode != 0:
        err = proc.stderr.decode().strip()
        # Format similar to gojq errors
        raise ValueError(f"gojq:({jq_expr}) {err}")

    lines = proc.stdout.decode().strip().split('\n')
    results = []
    for line in lines:
        if line:
            results.append(json.loads(line))
    return results


def _json_to_rows(data, jq_expr=None):
    """Convert JSON data to (columns, rows)."""
    if jq_expr:
        data = _apply_jq(data, jq_expr)

    if not isinstance(data, list):
        data = [data]

    if not data:
        return [], []

    columns = None
    rows = []

    for item in data:
        if isinstance(item, dict):
            if columns is None:
                columns = list(item.keys())
            row = []
            for c in columns:
                v = item.get(c, '')
                if isinstance(v, (dict, list)):
                    # Serialize nested objects/arrays as JSON strings
                    row.append(json.dumps(v, separators=(',', ':')))
                elif v is None:
                    row.append(None)
                elif isinstance(v, bool):
                    row.append('true' if v else 'false')
                else:
                    row.append(str(v))
            rows.append(row)
        else:
            if columns is None:
                columns = ['c1']
            if item is None:
                rows.append([None])
            elif isinstance(item, bool):
                rows.append(['true' if item else 'false'])
            else:
                rows.append([str(item)])

    if columns is None:
        columns = []

    return columns, rows


def read_json(f, jq_expr=None, limit=0, null_values=None, add_num=False, preread=1):
    """Read JSON/JSONL format. Returns (columns, rows)."""
    content = f.read()
    if isinstance(content, bytes):
        content = content.decode('utf-8')

