Output options:
  -oaq                enclose all fields in quotes for output.
  -ocrlf              use CRLF for output. End each output line with '\\r\\n' instead of '\\n'.
  -od string          field delimiter for output. (default ",")
  -oh                 output column name as header.
  -onowrap            do not wrap long lines(at/md only).
  -onull value        value(string) to convert from null on output.
  -oq string          quote character for output. (default "\\"")
  -out string         output file name.
  -out-without-guess  output without guessing (when using -out).
  -oz string          output compression format. [ gz | bz2 | zstd | lz4 | xz ]

Examples:
  $ trdsql "SELECT c1,c2 FROM test.csv"
  $ trdsql -oltsv "SELECT c1,c2 FROM test.json::.items"
  $ cat test.csv | trdsql -icsv -oltsv "SELECT c1,c2 FROM -"\
"""


# ============================================================
# Main
# ============================================================

def main():
    parser = argparse.ArgumentParser(add_help=False, prefix_chars='-')

    parser.add_argument('-A', metavar='string', default=None)
    parser.add_argument('-a', metavar='string', default=None)
    parser.add_argument('-config', metavar='string', default=None)
    parser.add_argument('-db', metavar='string', default=None)
    parser.add_argument('-dblist', action='store_true', default=False)
    parser.add_argument('-debug', action='store_true', default=False)
    parser.add_argument('-driver', metavar='string', default='sqlite3')
    parser.add_argument('-dsn', metavar='string', default='')
    parser.add_argument('-help', action='store_true', default=False)
    parser.add_argument('-q', metavar='string', default=None)
    parser.add_argument('-t', metavar='string', default=None)
    parser.add_argument('-version', action='store_true', default=False)

    parser.add_argument('-icsv', action='store_true', default=False)
    parser.add_argument('-ig', metavar='bool', default='true')
    parser.add_argument('-ijson', action='store_true', default=False)
    parser.add_argument('-iltsv', action='store_true', default=False)
    parser.add_argument('-itbln', action='store_true', default=False)
    parser.add_argument('-itext', action='store_true', default=False)
    parser.add_argument('-iwidth', action='store_true', default=False)
    parser.add_argument('-iyaml', action='store_true', default=False)

    parser.add_argument('-id', metavar='string', default=',')
    parser.add_argument('-ih', action='store_true', default=False)
    parser.add_argument('-ijq', metavar='string', default=None)
    parser.add_argument('-ilr', metavar='int', type=int, default=0)
    parser.add_argument('-inull', metavar='value', action='append', default=None)
    parser.add_argument('-inum', action='store_true', default=False)
    parser.add_argument('-ir', metavar='int', type=int, default=1)
    parser.add_argument('-is', metavar='int', type=int, default=0, dest='is_')

    parser.add_argument('-oat', action='store_true', default=False)
    parser.add_argument('-ocsv', action='store_true', default=False)
    parser.add_argument('-ojson', action='store_true', default=False)
    parser.add_argument('-ojsonl', action='store_true', default=False)
    parser.add_argument('-oltsv', action='store_true', default=False)
    parser.add_argument('-omd', action='store_true', default=False)
    parser.add_argument('-oraw', action='store_true', default=False)
    parser.add_argument('-otbln', action='store_true', default=False)
    parser.add_argument('-ovf', action='store_true', default=False)
    parser.add_argument('-oyaml', action='store_true', default=False)

    parser.add_argument('-oaq', action='store_true', default=False)
    parser.add_argument('-ocrlf', action='store_true', default=False)
    parser.add_argument('-od', metavar='string', default=',')
    parser.add_argument('-oh', action='store_true', default=False)
    parser.add_argument('-onowrap', action='store_true', default=False)
    parser.add_argument('-onull', metavar='value', action='append', default=None)
    parser.add_argument('-oq', metavar='string', default='"')
    parser.add_argument('-out', metavar='string', default=None)
    parser.add_argument('-out-without-guess', action='store_true', default=False,
                        dest='out_without_guess')
    parser.add_argument('-oz', metavar='string', default=None)

    parser.add_argument('sql', nargs='?', default=None)

    args = parser.parse_args()

    # -onull: last value wins
    if args.onull:
        args.onull = args.onull[-1]
    else:
        args.onull = None

    if args.help:
        print(USAGE)
        return 0

    if args.version:
        print(f"trdsql version {VERSION}")
        return 0

    # Load config
    config = None
    config_path_tried = None
    try:
        config, config_path_tried = load_config(args.config)
    except ValueError as e:
        log_error(f"ERROR: {e}")
        return 1

    if args.debug:
        if config:
            log_error(f"config found: {config_path_tried}")
        else:
            log_error(f"configOpen: open {config_path_tried}: no such file or directory")

    # Handle -dblist
    if args.dblist:
        if config and 'database' in config:
            db_cfg = config['database']
            if isinstance(db_cfg, dict):
                for name, info in sorted(db_cfg.items()):
                    driver = info.get('driver', 'sqlite3')
                    print(f"{name}:{driver}")
        return 0

    # Handle -db
    driver = args.driver
    dsn = args.dsn

    if args.db and config:
        db_cfg = config.get('database', {})
        if isinstance(db_cfg, dict) and args.db in db_cfg:
            info = db_cfg[args.db]
            driver = info.get('driver', driver)
            dsn = info.get('dsn', dsn)
            if args.debug:
                log_error(f">[driver: {args.db}:{driver}:{dsn}]")
        else:
            log_error(f"ERROR: db[{args.db}] does not found")
    elif args.db:
        log_error(f"ERROR: db[{args.db}] does not found")

    if args.debug:
        log_error(f"driver: {driver}, dsn: {dsn}")

    # Handle -a / -A
    if args.a:
        return do_analyze(args.a, args, only_suggest=False)
    if args.A:
        return do_analyze(args.A, args, only_suggest=True)

    # Get SQL
    sql = None
    if args.q:
        try:
            with open(args.q) as f:
                sql = f.read().strip()
        except FileNotFoundError:
            log_error(f"open {args.q}: no such file or directory")
            return 1
    elif args.t:
        sql = f"SELECT * FROM {args.t}"
    elif args.sql:
        sql = args.sql
    else:
        print(USAGE)
        return 2

    # Execute query
    columns, rows = execute_query(sql, args, debug=args.debug)
    if columns is None:
        return 1

    # Output
    out_file = None
    if args.out:
        try:
            out_file = open_output_file(args.out, args.oz)
        except Exception as e:
            log_error(f"open output: {e}")
            return 1

    try:
        output_result(columns, rows, args, out_file=out_file)
    finally:
        if out_file:
            out_file.close()

    return 0


if __name__ == '__main__':
    sys.exit(main())
